/// Every event pushed over the WebSocket stream. The CLI's `tail` prints these.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, ToSchema)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Event {
    AppearanceUpdated {
        user_id: String,
        appearance: Appearance,
    },
    TerminalOutput {
        session_id: Id,
