    },
    ObjectPresence {
        id: Id,
        channel_id: Id,
        user_ids: Vec<Id>,
    },
    ObjectCursor {
        id: Id,
        user_id: Id,
        x: f64,
        y: f64,
        page_id: String,
    },
    SettingsUpdated {
        settings: Settings,
    },
    MessageCreated(Message),
    MessageEdited(Message),
    MessageDeleted {
        id: Id,
        channel_id: Id,
    },
    Typing {
        channel_id: Id,
        user_id: Id,
    },
    CallState {
        channel_id: Id,
        participant_ids: Vec<Id>,
    },
    /// Only other DM members with a pending, unexpired invitation receive this.
    CallInvite {
        invitation_id: Id,
        channel_id: Id,
        from_user_id: Id,
        expires_at: i64,
    },
    CallInvitationState {
        call: CallInvitationState,
    },
    CallInviteAccepted {
        call: CallInvitationState,
        user_id: Id,
        answer_id: String,
    },
    CallInviteCancelled {
        call: CallInvitationState,
    },
    CallInviteExpired {
        call: CallInvitationState,
    },
    CallEnded {
        call: CallInvitationState,
    },
    Presence {
        user_id: Id,
        online: bool,
    },
    ReactionsUpdated {
        message_id: Id,
        channel_id: Id,
        reactions: Vec<Reaction>,
    },
    ReadStateUpdated {
        user_id: Id,
        state: ChannelReadState,
    },
    NotificationPreferencesUpdated {
        user_id: Id,
        preferences: NotificationPreferences,
    },
    Notification {
        user_id: Id,
        message: Message,
        reason: NotificationReason,
    },
    /// Reconnect or lag requires refetching channel state, presence, and calls. No replay is promised.
    Resync {
        reason: String,
    },
}

