        )?;
        eprintln!("{} / {} bytes", upload.offset, size);
    }
    let result: Upload = c.send(
        Method::POST,
        &format!("/uploads/{}/complete", upload.id),
        &serde_json::json!({}),
    )?;
    print(&result)
